Another problem this time with batching and draw ordering, I modified the `ui_material` example a bit to demonstrate:
```rust
use bevy::prelude::*;
use bevy_internal::{
    reflect::{TypePath, TypeUuid},
    render::render_resource::*,
};

fn main() {
    App::new()
        .add_plugins(DefaultPlugins)
        .add_plugins(UiMaterialPlugin::<CustomUiMaterial>::default())
        .add_systems(Startup, setup)
        .add_systems(Update, update)
        .run();
}

fn update(time: Res<Time>, mut ui_materials: ResMut<Assets<CustomUiMaterial>>) {
    for (_, material) in ui_materials.iter_mut() {
        material.fill_amount = time.elapsed_seconds() % 1.0;
        let new_color = Color::WHITE;
        material.color = new_color.into();
    }
}

fn setup(mut commands: Commands, mut ui_materials: ResMut<Assets<CustomUiMaterial>>) {
    // Camera so we can see UI
    commands.spawn(Camera2dBundle::default());


    commands
        .spawn(NodeBundle {
            style: Style {
                width: Val::Percent(100.0),
                align_items: AlignItems::Center,
                justify_content: JustifyContent::Center,
                ..default()
            },
            background_color: Color::BLACK.into(),
            ..default()
        })
        .with_children(|parent| {
            parent.spawn(NodeBundle {
                style: Style {
                    width: Val::Px(500.0),
                    height: Val::Px(500.0),
                    border: UiRect::all(Val::Px(10.)),
                    align_items: AlignItems::Center,
                    justify_content: JustifyContent::Center,
                    ..Default::default()
                },
                border_color: BorderColor(Color::WHITE),
                ..Default::default()
            }).with_children(|parent| {
                parent.spawn(NodeBundle {
                    style: Style {
                        position_type: PositionType::Absolute,
                        width: Val::Px(500.0),
                        height: Val::Px(25.0),
                        ..Default::default()
                    },
                    background_color: BackgroundColor(Color::GREEN),
                ..Default::default()
                });
                parent.spawn(MaterialNodeBundle {
                    style: Style {
                        position_type: PositionType::Absolute,
                        width: Val::Px(250.0),
                        height: Val::Px(250.0),
                        ..default()
                    },
                    material: ui_materials.add(CustomUiMaterial {
                        fill_amount: 0.0,
                        color: Color::WHITE.into(),
                    }),
                    ..default()
                });
                parent.spawn(NodeBundle {
                    style: Style {
                        position_type: PositionType::Absolute,
                        width: Val::Px(25.0),
                        height: Val::Px(500.0),
                        ..Default::default()
                    },
                    background_color: BackgroundColor(Color::RED),
                ..Default::default()
                });
            });
        });
}

#[derive(AsBindGroup, TypeUuid, TypePath, Debug, Clone)]
#[uuid = "7b5569c8-36d4-4c9d-acb7-d1754b385ab1"]
struct CustomUiMaterial {
    #[uniform(0)]
    fill_amount: f32,
    #[uniform(0)]
    color: Vec4,
}

impl UiMaterial for CustomUiMaterial {
    fn fragment_shader() -> ShaderRef {
        "shaders/circle_shader.wgsl".into()
    }
}
```
The circular section should be drawn in front of the green bar and behind the red bar, but it's drawn on top instead:

<img width="420" alt="ui-material-z-order-example" src="https://github.com/bevyengine/bevy/assets/27962798/6516395c-5517-4f2b-91bf-3530c6688c90">

I managed to force it to render correctly by disabling batching completely and merging #9062 which is a fix for some UI draw order bugs. 

<img width="436" alt="ui-material-z-order-example-2" src="https://github.com/bevyengine/bevy/assets/27962798/b1269005-1231-4684-8442-86791ea0e0dd">

The issue is that `prepare_uinodes` and `prepare_uimaterial_nodes` are working independently of each other. 

`prepare_ui_nodes` puts the black background, the border rects, the green bar, and the red bar altogether into one batch.
`prepare_ui_material` puts the circular section ui material node into another batch.
Then the batches are sorted and then drawn in order. The batch with regular nodes first, and then the UI material batch on top.
 `prepare_ui_nodes` has no idea that the red bar needs to be batched separately.

